"use strict";(globalThis.webpackChunkbook=globalThis.webpackChunkbook||[]).push([[849],{6164(e){e.exports=JSON.parse('{"version":{"pluginId":"default","version":"current","label":"Next","banner":null,"badge":false,"noIndex":false,"className":"docs-version-current","isLast":true,"docsSidebars":{"bookSidebar":[{"type":"link","href":"/docs/intro","label":"Introduction to Physical AI & Humanoid Robotics","docId":"intro","unlisted":false},{"type":"category","label":"Module 1: The Robotic Nervous System (ROS 2)","items":[{"type":"link","href":"/docs/module1/setup","label":"Setting up your ROS 2 Environment","docId":"module1/setup","unlisted":false},{"type":"link","href":"/docs/module1/nodes","label":"Understanding ROS 2 Nodes","docId":"module1/nodes","unlisted":false},{"type":"link","href":"/docs/module1/topics","label":"Understanding ROS 2 Topics","docId":"module1/topics","unlisted":false},{"type":"link","href":"/docs/module1/services","label":"Understanding ROS 2 Services","docId":"module1/services","unlisted":false},{"type":"link","href":"/docs/module1/rclpy-basics","label":"rclpy Basics: Building Robust ROS 2 Nodes in Python","docId":"module1/rclpy-basics","unlisted":false},{"type":"link","href":"/docs/module1/urdf-basics","label":"Modeling a Simple Humanoid with URDF","docId":"module1/urdf-basics","unlisted":false}],"collapsed":true,"collapsible":true},{"type":"category","label":"Module 2: The Digital Twin (Gazebo & Unity)","items":[{"type":"link","href":"/docs/module2/setup-gazebo","label":"Setting up ROS 2 and Gazebo for Digital Twin Simulation","docId":"module2/setup-gazebo","unlisted":false},{"type":"link","href":"/docs/module2/setup-unity","label":"Setting up Unity for Robotics","docId":"module2/setup-unity","unlisted":false},{"type":"link","href":"/docs/module2/physics-collision","label":"Physics Simulation and Collision Modeling","docId":"module2/physics-collision","unlisted":false},{"type":"link","href":"/docs/module2/sensor-sim","label":"Sensor Simulation (LiDAR, Depth, IMU)","docId":"module2/sensor-sim","unlisted":false},{"type":"link","href":"/docs/module2/gazebo-digital-twin","label":"Building a Basic Digital Twin in Gazebo","docId":"module2/gazebo-digital-twin","unlisted":false},{"type":"link","href":"/docs/module2/unity-hri","label":"Unity for Robot Visualization and Human-Robot Interaction","docId":"module2/unity-hri","unlisted":false}],"collapsed":true,"collapsible":true},{"type":"category","label":"Module 3: The AI-Robot Brain (NVIDIA Isaac)","items":[{"type":"link","href":"/docs/module3/setup-isaac","label":"Setting up Isaac Sim and Isaac ROS Environments","docId":"module3/setup-isaac","unlisted":false},{"type":"link","href":"/docs/module3/isaac-sim-basics","label":"Isaac Sim Basics and Photorealistic Simulation","docId":"module3/isaac-sim-basics","unlisted":false},{"type":"link","href":"/docs/module3/isaac-ros-perception","label":"Isaac ROS Fundamentals and Perception Modules","docId":"module3/isaac-ros-perception","unlisted":false},{"type":"link","href":"/docs/module3/isaac-ros-pipeline","label":"Creating a Basic Perception Pipeline with Isaac ROS","docId":"module3/isaac-ros-pipeline","unlisted":false},{"type":"link","href":"/docs/module3/nav2-humanoid-isaac","label":"Nav2 for Humanoids with Isaac Sim and VSLAM","docId":"module3/nav2-humanoid-isaac","unlisted":false}],"collapsed":true,"collapsible":true},{"type":"category","label":"Module 4: Vision-Language-Action (VLA)","items":[{"type":"link","href":"/docs/module4/intro","label":"Introduction to Vision-Language-Action (VLA) Systems","docId":"module4/intro","unlisted":false},{"type":"link","href":"/docs/module4/whisper-vision","label":"Whisper-Based Voice Commands and Vision Processing","docId":"module4/whisper-vision","unlisted":false},{"type":"link","href":"/docs/module4/llm-planning","label":"LLM Task Planning and Decomposition with Pseudo-Code","docId":"module4/llm-planning","unlisted":false},{"type":"link","href":"/docs/module4/ros2-mapping","label":"ROS 2 Action Mapping for VLA Systems","docId":"module4/ros2-mapping","unlisted":false},{"type":"link","href":"/docs/module4/capstone-architecture","label":"Full Capstone Humanoid Architecture","docId":"module4/capstone-architecture","unlisted":false}],"collapsed":true,"collapsible":true}]},"docs":{"intro":{"id":"intro","title":"Introduction to Physical AI & Humanoid Robotics","description":"Welcome to a journey into the fascinating world of Physical AI and Humanoid Robotics. This book is designed for students, researchers, and engineers who are eager to understand and build intelligent robotic systems that interact with the physical world.","sidebar":"bookSidebar"},"module1/nodes":{"id":"module1/nodes","title":"Understanding ROS 2 Nodes","description":"In ROS 2, a node is an executable process that performs computations. It\'s the fundamental building block of any ROS 2 system, representing a single logical unit of computation. Nodes can be thought of as individual programs or processes that work together to form a robotic application.","sidebar":"bookSidebar"},"module1/rclpy-basics":{"id":"module1/rclpy-basics","title":"rclpy Basics: Building Robust ROS 2 Nodes in Python","description":"This chapter delves into the fundamental aspects of rclpy, the Python client library for ROS 2. You will learn how to initialize and structure ROS 2 nodes, manage parameters, and understand the lifecycle of a ROS 2 application written in Python. This chapter complements the previous discussions on nodes, topics, and services by focusing on the rclpy programming interface.","sidebar":"bookSidebar"},"module1/services":{"id":"module1/services","title":"Understanding ROS 2 Services","description":"While ROS 2 topics provide a flexible publish/subscribe mechanism for continuous data streams, services offer a request/response communication pattern. This is ideal for situations where a node needs to send a request to another node and wait for a specific response.","sidebar":"bookSidebar"},"module1/setup":{"id":"module1/setup","title":"Setting up your ROS 2 Environment","description":"This chapter will guide you through the process of setting up a ROS 2 development environment on Ubuntu Linux, which is the recommended operating system for ROS 2 development. A properly configured environment is crucial for building, running, and interacting with ROS 2 applications.","sidebar":"bookSidebar"},"module1/topics":{"id":"module1/topics","title":"Understanding ROS 2 Topics","description":"Topics are the most common communication mechanism in ROS 2. They implement a publish/subscribe messaging pattern, allowing nodes to exchange data asynchronously.","sidebar":"bookSidebar"},"module1/urdf-basics":{"id":"module1/urdf-basics","title":"Modeling a Simple Humanoid with URDF","description":"This chapter will guide you through creating a simple humanoid robot model using URDF (Unified Robot Description Format) and visualizing it in RViz2.","sidebar":"bookSidebar"},"module2/gazebo-digital-twin":{"id":"module2/gazebo-digital-twin","title":"Building a Basic Digital Twin in Gazebo","description":"This chapter will guide you through creating a basic robot digital twin model in Gazebo, configuring its physics and collision properties, and attaching simulated sensors like LiDAR and IMU.","sidebar":"bookSidebar"},"module2/physics-collision":{"id":"module2/physics-collision","title":"Physics Simulation and Collision Modeling","description":"This chapter explores the fundamentals of physics simulation and collision modeling in the context of robot digital twins. Accurate simulation of physical interactions is critical for developing and testing robots safely and efficiently in a virtual environment before deploying them in the real world.","sidebar":"bookSidebar"},"module2/sensor-sim":{"id":"module2/sensor-sim","title":"Sensor Simulation (LiDAR, Depth, IMU)","description":"This chapter delves into the principles and techniques behind simulating common robot sensors like LiDAR, depth cameras, and Inertial Measurement Units (IMUs) in virtual environments. Accurate sensor simulation is paramount for developing robust perception, navigation, and control systems for robots without needing physical hardware.","sidebar":"bookSidebar"},"module2/setup-gazebo":{"id":"module2/setup-gazebo","title":"Setting up ROS 2 and Gazebo for Digital Twin Simulation","description":"This chapter provides a foundational guide for setting up your development environment to work with ROS 2 and Gazebo for robot simulation. A robust setup is crucial for building and interacting with digital twins, allowing you to develop and test robot behaviors in a virtual environment.","sidebar":"bookSidebar"},"module2/setup-unity":{"id":"module2/setup-unity","title":"Setting up Unity for Robotics","description":"Unity provides a powerful platform for 3D visualization, realistic simulation, and developing interactive Human-Robot Interaction (HRI) applications. This chapter guides you through setting up Unity for robotics development, focusing on its integration with ROS 2.","sidebar":"bookSidebar"},"module2/unity-hri":{"id":"module2/unity-hri","title":"Unity for Robot Visualization and Human-Robot Interaction","description":"Unity is a powerful platform for creating interactive 3D environments, making it ideal for visualizing robot digital twins and developing intuitive human-robot interfaces (HRI). This chapter guides you through using Unity for robot visualization and implementing basic HRI, specifically focusing on how to integrate with ROS 2 for sending commands.","sidebar":"bookSidebar"},"module3/isaac-ros-perception":{"id":"module3/isaac-ros-perception","title":"Isaac ROS Fundamentals and Perception Modules","description":"This chapter explores NVIDIA Isaac ROS, a collection of hardware-accelerated packages for ROS 2 that enables high-performance AI perception for robots. Leveraging NVIDIA GPUs, Isaac ROS significantly boosts the capabilities of robotic systems by providing optimized modules for tasks like image processing, depth estimation, and object detection.","sidebar":"bookSidebar"},"module3/isaac-ros-pipeline":{"id":"module3/isaac-ros-pipeline","title":"Creating a Basic Perception Pipeline with Isaac ROS","description":"This chapter guides you through setting up a fundamental perception pipeline using NVIDIA Isaac ROS modules, and visualizing its output. We will focus on integrating Isaac Sim as the sensor data source and an Isaac ROS Docker container for processing the data.","sidebar":"bookSidebar"},"module3/isaac-sim-basics":{"id":"module3/isaac-sim-basics","title":"Isaac Sim Basics and Photorealistic Simulation","description":"This chapter introduces NVIDIA Isaac Sim, a powerful platform for photorealistic robotic simulation and synthetic data generation. Built on NVIDIA Omniverse, Isaac Sim provides a highly realistic environment for developing, testing, and deploying AI-driven robots.","sidebar":"bookSidebar"},"module3/nav2-humanoid-isaac":{"id":"module3/nav2-humanoid-isaac","title":"Nav2 for Humanoids with Isaac Sim and VSLAM","description":"This chapter explores how to integrate the ROS 2 Navigation Stack (Nav2) with Isaac Sim for autonomous navigation of humanoid robots, utilizing Visual SLAM (VSLAM) for localization. Navigating complex humanoid robots autonomously in dynamic environments presents unique challenges that can be effectively addressed through advanced simulation and perception techniques.","sidebar":"bookSidebar"},"module3/setup-isaac":{"id":"module3/setup-isaac","title":"Setting up Isaac Sim and Isaac ROS Environments","description":"This chapter provides a foundational guide for setting up your development environment to work with NVIDIA Isaac Sim and Isaac ROS. This powerful combination allows for advanced robotics simulation, photorealistic rendering, synthetic data generation, and hardware-accelerated AI perception.","sidebar":"bookSidebar"},"module4/capstone-architecture":{"id":"module4/capstone-architecture","title":"Full Capstone Humanoid Architecture","description":"Introduction","sidebar":"bookSidebar"},"module4/intro":{"id":"module4/intro","title":"Introduction to Vision-Language-Action (VLA) Systems","description":"Overview","sidebar":"bookSidebar"},"module4/llm-planning":{"id":"module4/llm-planning","title":"LLM Task Planning and Decomposition with Pseudo-Code","description":"Introduction","sidebar":"bookSidebar"},"module4/ros2-mapping":{"id":"module4/ros2-mapping","title":"ROS 2 Action Mapping for VLA Systems","description":"Introduction","sidebar":"bookSidebar"},"module4/whisper-vision":{"id":"module4/whisper-vision","title":"Whisper-Based Voice Commands and Vision Processing","description":"Introduction","sidebar":"bookSidebar"},"tutorial-basics/congratulations":{"id":"tutorial-basics/congratulations","title":"Congratulations!","description":"You have just learned the basics of Docusaurus and made some changes to the initial template."},"tutorial-basics/create-a-blog-post":{"id":"tutorial-basics/create-a-blog-post","title":"Create a Blog Post","description":"Docusaurus creates a page for each blog post, but also a blog index page, a tag system, an RSS feed..."},"tutorial-basics/create-a-document":{"id":"tutorial-basics/create-a-document","title":"Create a Document","description":"Documents are groups of pages connected through:"},"tutorial-basics/create-a-page":{"id":"tutorial-basics/create-a-page","title":"Create a Page","description":"Add Markdown or React files to src/pages to create a standalone page:"},"tutorial-basics/deploy-your-site":{"id":"tutorial-basics/deploy-your-site","title":"Deploy your site","description":"Docusaurus is a static-site-generator (also called Jamstack)."},"tutorial-basics/markdown-features":{"id":"tutorial-basics/markdown-features","title":"Markdown Features","description":"Docusaurus supports Markdown and a few additional features."},"tutorial-extras/manage-docs-versions":{"id":"tutorial-extras/manage-docs-versions","title":"Manage Docs Versions","description":"Docusaurus can manage multiple versions of your docs."},"tutorial-extras/translate-your-site":{"id":"tutorial-extras/translate-your-site","title":"Translate your site","description":"Let\'s translate docs/intro.md to French."}}}}')}}]);